def calculate_sequence():
    a = {1: 10}
    print(f"a_1 = {a[1]}")
    for n in range(1, 6):
        a_n = a[n]
        # a_{n+1} = 6a_n - 2^{n+2} - 3^{n+1} + 5
        n_plus_1 = n + 1
        a_n_plus_1 = 6 * a_n - (2**(n + 2)) - (3**(n + 1)) + 5
        a[n_plus_1] = a_n_plus_1
        print(f"a_{n+1} = {a_n_plus_1}")
    return {i: a[i] for i in range(1, 7)}

results = calculate_sequence()
print("\nAll results:", results)
